        INSERT INTO grammar_timestamps (lesson_id, time_sec, time_str, pattern, title, summary, sort_order) VALUES
        (v_lesson_id, 15, '00:15', 'わたし・あなた・あの人', 'Tổng quan bài 1 & Đại từ xưng hô', 'Giới thiệu bản thân và cách xưng hô lịch sự trong tiếng Nhật.', 1),
        (v_lesson_id, 90, '01:30', 'N1 は N2 です', 'Mẫu 1: Câu khẳng định danh từ', 'Cấu trúc cơ bản khẳng định N1 là N2. Trợ từ は đọc là WA.', 2),
        (v_lesson_id, 320, '05:20', 'N1 は N2 じゃ / ではありません', 'Mẫu 2: Câu phủ định danh từ', 'Phủ định N1 không phải là N2. じゃありません dùng trong giao tiếp, ではありません dùng trong văn viết.', 3),
        (v_lesson_id, 580, '09:40', 'Câu + か', 'Mẫu 3: Câu hỏi nghi vấn Có/Không', 'Thêm trợ từ か vào cuối câu để tạo câu hỏi xác nhận.', 4),
        (v_lesson_id, 825, '13:45', 'N も', 'Mẫu 4: Trợ từ "Cũng"', 'Dùng trợ từ も thay thế cho は khi có cùng đặc điểm với đối tượng trước đó.', 5),
        (v_lesson_id, 1080, '18:00', 'N1 の N2', 'Mẫu 5: Trợ từ sở hữu & giải thích', 'N1 bổ nghĩa cho N2: quyền sở hữu (của tôi) hoặc trực thuộc (công ty, trường học).', 6);
        INSERT INTO grammar_cheatsheets (lesson_id, pattern, badge, meaning, structure, nuance, examples_json, sort_order) VALUES
