-- ====================================================================
-- V26: Dữ liệu Khởi tạo Trọn bộ 5 Cấp độ Ngữ pháp (N5, N4, N3, N2, N1)
-- Bao gồm 131 Video Bài giảng thật, thời lượng YouTube & phân loại phần bài
-- ====================================================================

-- 1. Khởi tạo 5 Cấp độ Ngữ pháp
ON CONFLICT (level_code) DO UPDATE SET
curriculum_name = EXCLUDED.curriculum_name,
total_lessons = EXCLUDED.total_lessons,
description = EXCLUDED.description;

-- 2. Khởi tạo 131 Bài học Video
ON CONFLICT (level_code, sort_order) DO UPDATE SET
lesson_number = EXCLUDED.lesson_number,
part_number = EXCLUDED.part_number,
title_vi = EXCLUDED.title_vi,
title_ja = EXCLUDED.title_ja,
video_id = EXCLUDED.video_id,
duration_str = EXCLUDED.duration_str,
duration_sec = EXCLUDED.duration_sec,
is_active = EXCLUDED.is_active;

-- 3. Khởi tạo Mốc thời gian mẫu cho N5 Bài 1
DO $$
DECLARE
    v_lesson_id BIGINT;
BEGIN
    SELECT id INTO v_lesson_id FROM grammar_lessons WHERE level_code = 'N5' AND sort_order = 1;
    IF v_lesson_id IS NOT NULL THEN
        DELETE FROM grammar_timestamps WHERE lesson_id = v_lesson_id;

        DELETE FROM grammar_cheatsheets WHERE lesson_id = v_lesson_id;
        '[{"ja": "わたしは マイケル です。", "furigana": "わたしは マイケル です。", "vi": "Tôi là Michael."}, {"ja": "サントスさんは ブラジル人 です。", "furigana": "サントスさんは ブラジルじん です。", "vi": "Anh Santos là người Brazil."}]'::jsonb, 1),
        (v_lesson_id, 'N1 は N2 じゃ／ではありません', 'Phủ định', 'N1 không phải là N2', 'Danh từ 1 + は + Danh từ 2 + じゃ／ではありません', '[じゃありません] thường dùng trong hội thoại hàng ngày. [ではありません] trang trọng hơn, dùng trong bài thi JLPT hoặc văn viết.',
        '[{"ja": "サントスさんは 学生じゃ ありません。", "furigana": "サントスさんは がくせいじゃ ありません。", "vi": "Anh Santos không phải là sinh viên."}]'::jsonb, 2),
        (v_lesson_id, 'Câu + か', 'Nghi vấn', '... phải không? / ... có phải không?', 'Câu khẳng định + か？', 'Cuối câu nghi vấn lên giọng nhẹ ở từ [か]. Trả lời dùng [はい] hoặc [いいえ].',
        '[{"ja": "ミラーさんは アメリカ人ですか。…はい、アメリカ人です。", "furigana": "ミラーさんは アメリカじんですか。…はい、アメリカじんです。", "vi": "Anh Miller có phải người Mỹ không? ... Vâng, là người Mỹ."}]'::jsonb, 3);

        DELETE FROM grammar_quizzes WHERE lesson_id = v_lesson_id;
        '[{"id": "f1", "text": "は"}, {"id": "f2", "text": "アメリカ"}, {"id": "f3", "text": "から"}, {"id": "f4", "text": "来ました"}]'::jsonb, null, 'は', 'Thứ tự đúng: わたし [は] [アメリカ] [から] [来ました] マイク・ミラーです。(Vị trí sao số 1 là は).', 1),
        (v_lesson_id, 'MCQ', 'Chọn trợ từ thích hợp điền vào chỗ trống: サントスさん _____ ブラジル人です。', null, null, null, null,
        '["は", "が", "を", "に"]'::jsonb, 'は', 'Trợ từ [は] biểu thị chủ đề của câu: Anh Santos là người Brazil.', 2),
        (v_lesson_id, 'MCQ', 'Dạng phủ định trang trọng của「です」dùng trong bài thi JLPT là gì?', null, null, null, null,
        '["ではありません", "じゃありません", "でした", "くありません"]'::jsonb, 'ではありません', '[ではありません] là cách phủ định trang trọng tiêu chuẩn trong văn viết và bài thi.', 3);
    END IF;
END $$;
